package com.ptms.service; import com.ptms.domain.*; import com.ptms.dto.*; import com.ptms.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class TeamService{private final TeamRepository r;public TeamService(TeamRepository r){this.r=r;}public List<TeamDto>all(){return r.findAllByOrderByNameAsc().stream().map(this::dto).toList();}public TeamDto save(TeamDto d){Team x=d.id()==null?new Team():r.findById(d.id()).orElseThrow();x.setName(d.name().trim());x.setDepartment(d.department());x.setDescription(d.description());x.setEnabled(d.enabled());return dto(r.save(x));}public void delete(Long id){r.deleteById(id);}private TeamDto dto(Team x){return new TeamDto(x.getId(),x.getName(),x.getDepartment(),x.getDescription(),x.isEnabled());}}
